"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import styles from "./SiteHeader.module.css";

const nav = [
  ["About", "/about"],
  ["Services", "/services"],
  ["Countries", "/countries"],
  ["Work Permit", "/work-permit"],
  ["Contact", "/contact"],
];

export function SiteHeader() {
  const pathname = usePathname();
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    setMenuOpen(false);
  }, [pathname]);

  return (
    <header className={styles.header}>
      <div className={styles.shell}>
        <div className={styles.inner}>
          <Link href="/" className={styles.brand}>
            <span className={styles.brandMark}>GW</span>
            <span className={styles.brandText}>
              <strong>GetWorkPermits</strong>
              <small>Global Employment Platform</small>
            </span>
          </Link>

          <button
            type="button"
            className={styles.menuToggle}
            onClick={() => setMenuOpen((value) => !value)}
            aria-expanded={menuOpen}
            aria-label="Toggle navigation"
          >
            <span />
            <span />
          </button>

          <nav className={`${styles.navWrap} ${menuOpen ? styles.navWrapOpen : ""}`}>
            <div className={styles.nav}>
              {nav.map(([label, href]) => {
                const isActive = pathname === href;

                return (
                  <Link
                    key={href}
                    href={href}
                    className={`${styles.navLink} ${isActive ? styles.navLinkActive : ""}`}
                  >
                    {label}
                  </Link>
                );
              })}
            </div>

            <Link href="/contact" className={styles.action}>
              Get Consultation
            </Link>
          </nav>
        </div>
      </div>
    </header>
  );
}

