"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import styles from "./HomeHero.module.css";

type HeroSlide = {
  badge: string;
  title: string;
  text: string;
  image: string;
};

const heroSlides: HeroSlide[] = [
  {
    badge: "Clear Work Permit Planning",
    title: "Find the right work permit path with clearer expert guidance",
    text: "Compare destinations, understand your best-fit route, and move forward with practical support before you commit time and money.",
    image: "/home/home-hero-airplane.jpg",
  },
  {
    badge: "Global Work Permit Specialists",
    title: "Build your overseas career with confident step-by-step support",
    text: "From country selection to application readiness, GetWorkPermits helps professionals navigate international opportunities with more confidence.",
    image:
      "https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1800&q=80",
  },
  {
    badge: "Fast And Transparent Support",
    title: "Move from uncertainty to action with faster permit planning",
    text: "Explore work permits across leading destinations with expert advice, practical next steps, and a smoother route to action.",
    image:
      "https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1800&q=80",
  },
];

function splitWords(text: string) {
  return text.split(" ").map((word, index) => (
    <span
      key={`${word}-${index}`}
      className={styles.word}
      style={{ animationDelay: `${0.07 * index}s` }}
    >
      {word}
    </span>
  ));
}

function splitLetters(text: string) {
  return text.split("").map((char, index) => (
    <span
      key={`${char}-${index}`}
      className={styles.letter}
      style={{ animationDelay: `${0.024 * index}s` }}
      aria-hidden="true"
    >
      {char === " " ? "\u00A0" : char}
    </span>
  ));
}

export function HomeHero() {
  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    const timer = window.setInterval(() => {
      setActiveIndex((current) => (current + 1) % heroSlides.length);
    }, 5200);

    return () => window.clearInterval(timer);
  }, []);

  const activeSlide = useMemo(() => heroSlides[activeIndex], [activeIndex]);

  return (
    <section className={styles.hero}>
      <div className={styles.slider} aria-hidden="true">
        {heroSlides.map((slide, index) => (
          <div
            key={slide.title}
            className={`${styles.media} ${index === activeIndex ? styles.mediaActive : ""}`}
            style={{ backgroundImage: `url("${slide.image}")` }}
          />
        ))}
      </div>

      <div className={styles.photoCollage} aria-hidden="true"><img src="/services/new-zealand.jpg" alt="" /><img src="/services/italy.jpg" alt="" /><img src="/services/canada.jpg" alt="" /></div>
      <div className={styles.overlay} />
      <div className={styles.leftShade} />

      <div className={styles.inner}>
        <div className={styles.copy}>
          <div className={styles.ratingRow}>
            <div className={styles.stars} aria-hidden="true">
              <span>{"\u2605"}</span>
              <span>{"\u2605"}</span>
              <span>{"\u2605"}</span>
              <span>{"\u2605"}</span>
              <span>{"\u2606"}</span>
            </div>
            <div key={`badge-${activeIndex}`} className={styles.badge}>
              {activeSlide.badge}
            </div>
          </div>

          <h1 key={`title-${activeIndex}`} className={styles.title}>
            {splitWords(activeSlide.title)}
          </h1>

          <p key={`text-${activeIndex}`} className={styles.text}>
            {activeSlide.text}
          </p>

          <div className={styles.actionRow}>
            <div className={styles.avatarGroup} aria-hidden="true">
              <span
                className={styles.avatar}
                style={{
                  backgroundImage:
                    'url("https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80")',
                }}
              />
              <span
                className={styles.avatar}
                style={{
                  backgroundImage:
                    'url("https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=200&q=80")',
                }}
              />
              <span
                className={styles.avatar}
                style={{
                  backgroundImage:
                    'url("https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=200&q=80")',
                }}
              />
            </div>

            <Link href="/contact" className={styles.primaryCta}>
              <span className={styles.primaryCtaText}>
                {splitLetters("Free Consultation")}
              </span>
              <span className={styles.primaryCtaArrow}>{"\u2197"}</span>
            </Link>
          </div>
        </div>

        <div className={styles.sidePanel}>
          <div className={styles.sideCard}>
            <p className={styles.sideEyebrow}>Why GetWorkPermits</p>
            <h2 className={styles.sideTitle}>
              Smarter guidance for professionals planning to work abroad.
            </h2>
            <p className={styles.sideText}>
              We combine expert advisory, documentation support, and practical country guidance so
              applicants can move faster with fewer mistakes.
            </p>

            <div className={styles.sideGrid}>
              <div className={styles.sideStat}>
                <span>Coverage</span>
                <strong>12+ destinations</strong>
              </div>
              <div className={styles.sideStat}>
                <span>Support</span>
                <strong>Experts + AI</strong>
              </div>
              <div className={styles.sideStat}>
                <span>Style</span>
                <strong>Clear process</strong>
              </div>
              <div className={styles.sideStat}>
                <span>Goal</span>
                <strong>Faster decisions</strong>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className={styles.pagination} aria-label="Hero slides">
        {heroSlides.map((slide, index) => (
          <button
            key={slide.title}
            type="button"
            className={`${styles.dot} ${index === activeIndex ? styles.dotActive : ""}`}
            onClick={() => setActiveIndex(index)}
            aria-label={`Go to slide ${index + 1}`}
            aria-pressed={index === activeIndex}
          />
        ))}
      </div>
    </section>
  );
}

